import '../../src/native-http-recorder.js';
import { type DiagnosticCapture, diagnosticCaptureBudgetBytes } from '@webdcc/model-proxy';

const endpoint = process.argv[2]!;
const retained: number[] = [];
const first = await fetch(`${endpoint}?held`);
const reader = first.body!.getReader();
const firstText = Buffer.from((await reader.read()).value!).toString();
retained.push(diagnosticCaptureBudgetBytes());
// Independent module copies (as in a bundled preload) use the same process pool.
const independent = await import(new URL('../../../testing/model-proxy/src/redaction.ts?independent', import.meta.url).href);
const competing: DiagnosticCapture = new independent.DiagnosticCapture();
competing.push(Buffer.from('x'), 0);
const moduleCopyReason = competing.limitReason; competing.release();
const secondText = await (await fetch(`${endpoint}?second`)).text();
retained.push(diagnosticCaptureBudgetBytes());
await reader.cancel('native cancellation');
retained.push(diagnosticCaptureBudgetBytes());
const thirdText = await (await fetch(`${endpoint}?third`)).text();
retained.push(diagnosticCaptureBudgetBytes());
const noBodyStatus = (await fetch(`${endpoint}?no-body`, { method: 'POST', body: 'input' })).status;
await new Promise<void>(resolve => setImmediate(resolve));
retained.push(diagnosticCaptureBudgetBytes());
const failed = await fetch(`${endpoint}?failure`, { method: 'POST', body: 'input' }).then(() => false, () => true);
await new Promise<void>(resolve => setImmediate(resolve));
retained.push(diagnosticCaptureBudgetBytes());
const partialFailed = await fetch(`${endpoint}?stream-failure`).then(response => response.text()).then(() => false, () => true);
retained.push(diagnosticCaptureBudgetBytes());
const source = new ReadableStream<Uint8Array>({ start(controller) { controller.enqueue(new TextEncoder().encode('x')); } });
const pendingUploadFailed = await fetch(`${endpoint}?upload-failure`, Object.assign({ method: 'POST', body: source }, { duplex: 'half' })).then(() => false, () => true);
await new Promise<void>(resolve => setImmediate(resolve));
retained.push(diagnosticCaptureBudgetBytes());
const controller = new AbortController();
const unread = await fetch(`${endpoint}?signal`, { signal: controller.signal });
await new Promise<void>(resolve => setTimeout(resolve, 10));
retained.push(diagnosticCaptureBudgetBytes());
controller.abort('native abort');
await new Promise<void>(resolve => setImmediate(resolve));
retained.push(diagnosticCaptureBudgetBytes());
await unread.body?.cancel().catch(() => undefined);
process.send?.({ firstText, secondText, thirdText, noBodyStatus, failed, partialFailed, pendingUploadFailed, retained, moduleCopyReason });
process.disconnect();
